#include <cstdio>
#include <vector>

int main() {
    int n;
    scanf("%d", &n);
    std::vector<long long> v(n);
    for (int i = 0; i < n; ++i) scanf("%lld", &v[i]);

    if (n == 0) { printf("\n"); return 0; }

    int slow = 0, fast = 0;
    while (fast + 1 < n) {      // fast 还能走两步
        slow += 1;
        fast += 2;
    }
    printf("%lld\n", v[slow]);
    return 0;
}
